Given an array of integers arr[], move all the zeros to the end of the array while maintaining the relative order of all non-zero elements.Examples: Input: arr[] = [1, 2, 0, 4, 3, 0, 5, 0]Output: [1, 2, 4, 3, 5, 0, 0, 0]Explanation: There are three 0s that are moved to the end.Input: arr[] = [10, 20, 30]Output: [10, 20, 30]Explanation: No change in array as there are no 0s.Input: arr[] = [0, 0]Output: [0, 0]Explanation: No change in array as there are all 0s.Try It YourselfTable of Content[Naive Approach] Using Temporary Array - O(n) Time and O(n) Space[Better Approach] Two Traversals-O(n) Time and O(1) space[Expected Approach] One Traversal-O(n) Time and O(1) space[Naive Approach] Using Temporary Array - O(n) Time and O(n) SpaceThe idea is to use a temporary array of the same size, copy all non-zero elements into it, fill the remaining positions with zeros, and then copy the temporary array back to the original array.Working: 
            C++

    #include <iostream>
#include <vector>

using namespace std;

void pushZerosToEnd(vector<int> &arr)
{
    int n = arr.size();
    vector<int> temp(n);

    // to keep track of the index in temp[]
    int j = 0;

    // Copy non-zero elements to temp[]
    for (int i = 0; i < n; i++)
    {
        if (arr[i] != 0)
            temp[j++] = arr[i];
    }

    // Fill remaining positions in temp[] with zeros
    while (j < n)
    {
        temp[j++] = 0;
    }

    // Copy all the elements from temp[] to arr[]
    for (int i = 0; i < n; i++)
        arr[i] = temp[i];
}

int main()
{
    vector<int> arr = {1, 2, 0, 4, 3, 0, 5, 0};
    pushZerosToEnd(arr);

    for (int num : arr)
    {
        cout << num << " ";
    }
    return 0;
}


